    if(type==='date'){if(!/^\d{4}-\d{2}-\d{2}/.test(String(v)))return `<c r="${ref}" s="11" t="inlineStr"><is><t>${x(v)}</t></is></c>`;return `<c r="${ref}" s="${s}"><v>${serial(v)}</v></c>`}
