function renderDashboard(){const e=$('#page-dashboard'),m=M();
  if(!e.dataset.built){e.innerHTML=`<div class="hero" id="dHero"></div><div class="kc-grid" id="dK"></div>
    <div class="grid-a"><div class="card"><div class="card-h"><h3>Chi phí bảo trì, sửa chữa 12 tháng</h3><div class="r legend">${KINDS.map(k=>`<span><i style="background:${KCOL[k]}"></i>${k}</span>`).join('')}</div></div><div class="card-b"><div class="msum" id="dMs"></div><div id="dCh"></div></div></div>
      <div class="card"><div class="card-h"><h3>Thiết bị theo hiện trạng</h3></div><div class="card-b" id="dSt"></div></div></div>
    <div class="grid-b"><div class="card"><div class="card-h"><h3>Lịch bảo trì 14 ngày tới</h3><div class="r"><button class="btn sm" onclick="go('cal')">Xem lịch</button></div></div><div class="card-b" id="dNext"></div></div>
      <div class="card"><div class="card-h"><h3>Quá hạn bảo trì</h3><span class="cnt-b" id="dQc"></span></div><div class="card-b" id="dQh"></div></div>
      <div class="card"><div class="card-h"><h3>Sắp hết bảo hành</h3><span class="hint">90 ngày tới</span></div><div class="card-b" id="dW"></div></div></div>
    <div class="grid-c"><div class="card"><div class="card-h"><h3>Thiết bị theo bộ phận</h3></div><div class="card-b" id="dDept"></div></div>
      <div class="card"><div class="card-h"><h3>Thiết bị tốn chi phí nhất 12 tháng</h3><div class="r"><button class="btn sm" onclick="go('rep')">Báo cáo</button></div></div><div class="card-b" id="dTop"></div></div></div>`;e.dataset.built=1}
  const live=S.tb.filter(t=>t.status!=='tl'),N=live.length,ok=live.filter(t=>t.status==='hd').length,sua=live.filter(t=>t.status==='sua').length,hong=live.filter(t=>t.status==='hong').length;
  const val=sum(live,t=>t.price),ms=monthsBack(12),mk=k=>{const [y,mo]=k.split('-');return [k+'-01',ymd(new Date(+y,+mo,0))]};
  const ser=KINDS.map(k=>ms.map(x=>{const [f,t]=mk(x);return sum(S.logs.filter(l=>l.kind===k&&l.d>=f&&l.d<=t),l=>l.cost)}));
  const tot=ms.map((_,i)=>sum(ser,s=>s[i])),cnt=ms.map(x=>{const [f,t]=mk(x);return S.logs.filter(l=>l.d>=f&&l.d<=t).length});
  const plans=S.plans.map(p=>({p,s:planSt(p,m),n:nextOf(p,m)})),qh=plans.filter(x=>x.s==='qh'),soon=plans.filter(x=>x.s!=='off'&&x.n>=TODAYS&&x.n<=addDays(TODAYS,14)).sort((a,b)=>a.n.localeCompare(b.n));
  const wSoon=live.filter(t=>t.warEnd&&diffDays(TODAYS,t.warEnd)>=0&&diffDays(TODAYS,t.warEnd)<=90).sort((a,b)=>a.warEnd.localeCompare(b.warEnd));
  const r=rangeOf('month'),cm=sum(logCost(r.from,TODAYS),l=>l.cost),pm=sum(logCost(r.pfrom,r.pto),l=>l.cost);
  $('#dHero').innerHTML=`<div><div class="h-k">THIẾT BỊ ĐANG QUẢN LÝ</div><div class="h-v"><span data-count="${N}">0</span> <small>thiết bị</small></div>
      <div class="h-sub"><span>Nguyên giá ${short(val)} ₫ · ${[...new Set(live.map(t=>t.dept))].length} bộ phận</span></div>
      <div class="h-stats"><div><b data-count="${ok}">0</b><span>Đang hoạt động</span></div><div><b data-count="${sua+hong}">0</b><span>Hỏng, đang sửa</span></div><div><b data-count="${qh.length}">0</b><span>Quá hạn bảo trì</span></div></div>
      <div class="h-act"><button class="hbtn" onclick="LGC.open()">+ Ghi nhật ký bảo trì</button><button class="hbtn ghost" onclick="go('cal')">Lịch bảo trì</button></div></div>
    <div class="h-chart"><div class="h-ct"><span>Chi phí bảo trì 12 tháng</span><span>Tổng <b>${short(sum(tot))} ₫</b></span></div>${heroArea(ms.map(mLabel),tot,money,'Chi phí ')}</div>
    <div class="h-ring">${ring(N?ok/N*100:0,Math.round(N?ok/N*100:0)+'%','đang hoạt động')}<b>${ok}/${N} thiết bị</b><span>${hong} hỏng · ${sua} đang sửa</span></div>`;
  $('#dK').innerHTML=kc({c:'#16a36a',cb:'var(--inbg)',icon:IC.check,label:'Đang hoạt động',value:ok,unit:'thiết bị',sub:`${S.tb.filter(t=>t.status==='tl').length} thiết bị đã thanh lý`,pill:`<span class="pill pu">${Math.round(N?ok/N*100:0)}%</span>`})
    +kc({c:'#e0384a',cb:'var(--dangerbg)',icon:IC.warn,label:'Hỏng, đang sửa',value:sua+hong,unit:'thiết bị',sub:`${hong} hỏng · ${sua} đang sửa`,pill:sua+hong?'<span class="pill pd">Cần xử lý</span>':'<span class="pill pu">Ổn</span>'})
    +kc({c:'#e6a100',cb:'var(--warnbg)',icon:IC.cal,label:'Bảo trì quá hạn, đến hạn',value:qh.length+plans.filter(x=>x.s==='dh').length,unit:'việc',sub:`${qh.length} quá hạn · ${plans.filter(x=>x.s==='dh').length} đến hạn trong 7 ngày`})
    +kc({c:CSSV('--chu-dao'),cb:'var(--cd-nhat)',icon:IC.money,label:'Chi phí tháng này',value:cm,unit:'₫',pill:pill(cm,pm,r.cmp,true),sub:`${logCost(r.from,TODAYS).length} phiếu · cùng kỳ tháng trước ${short(pm)} ₫`,data:tot});
  $('#dMs').innerHTML=`<div><small>Tổng chi phí 12 tháng</small><b style="color:var(--chu-dao)">${short(sum(tot))} ₫</b></div><div><small>Sửa chữa, thay thế</small><b style="color:#f0663a">${short(sum(ser[2])+sum(ser[3]))} ₫</b></div><div><small>Bảo trì định kỳ, kiểm định</small><b>${short(sum(ser[0])+sum(ser[1]))} ₫</b></div><div><small>Số lượt bảo trì, sửa</small><b>${fmt(sum(cnt))}</b></div>`;
  $('#dCh').innerHTML=combo({labels:ms.map(mLabel),tipL:ms.map(mName),stack:true,bars:KINDS.map((k,i)=>({name:k,data:ser[i],color:KCOL[k]})),hl:11,H:290,bw:26});
  $('#dSt').innerHTML=donut(Object.keys(STS).map(k=>({label:STS[k][1],value:S.tb.filter(t=>t.status===k).length,color:STS[k][2]})).filter(x=>x.value),'Thiết bị',v=>fmt(v));
  const pli=(x,btn)=>{const t=tbOf(x.p.tb),d=diffDays(TODAYS,x.n);return `<div class="li"><span class="tico ${d<0?'bad':d<=7?'warn':''}">${IC.tool}</span><div class="meta"><b>${esc(x.p.task)}</b><small>${esc(t?t.code+' '+t.name:'')} · ${vnDate(x.n)}</small></div><div class="v">${dLeftH(d)}${btn?`<button class="btn sm in" style="margin-top:4px" onclick="logDone('${x.p.id}')">Ghi nhận</button>`:''}</div></div>`};
  $('#dNext').innerHTML=soon.length?soon.slice(0,6).map(x=>pli(x)).join('')+(soon.length>6?`<div class="muted" style="font-size:12.5px;padding-top:8px">và ${soon.length-6} việc khác</div>`:''):'<div class="empty">Không có việc nào trong 14 ngày tới</div>';
  $('#dQc').textContent=qh.length?qh.length+' việc':'';
  $('#dQh').innerHTML=qh.length?qh.sort((a,b)=>a.n.localeCompare(b.n)).slice(0,5).map(x=>pli(x,1)).join(''):'<div class="empty">Không có việc quá hạn</div>';
  $('#dW').innerHTML=wSoon.length?wSoon.map(t=>{const d=diffDays(TODAYS,t.warEnd);return `<div class="li click" onclick="tbView('${t.id}')"><span class="tico warn">${IC.shield}</span><div class="meta"><b>${esc(t.name)}</b><small>${esc(t.code)} · ${esc((nccOf(t.sup)||{}).name||'')}</small><div class="pbar"><i style="width:${Math.max(4,100-d/90*100)}%;background:#e6a100"></i></div></div><div class="v">${vnDate(t.warEnd)}<small>còn ${d} ngày</small></div></div>`}).join(''):'<div class="empty">Không có thiết bị sắp hết bảo hành</div>';
  const byD=groupBy(live,t=>t.dept);
  $('#dDept').innerHTML=hbars(Object.entries(byD).sort((a,b)=>b[1].length-a[1].length).map(([d,ts])=>{const bad=ts.filter(t=>t.status!=='hd').length;return {label:d,value:ts.length,sub:bad?bad+' hỏng/sửa':'đều hoạt động',color:bad?'linear-gradient(90deg,var(--chu-dao),#e6a100)':'var(--chu-dao)',tip:d+': '+ts.length+' thiết bị, nguyên giá '+short(sum(ts,t=>t.price))+' ₫'}}),v=>fmt(v)+' TB');
  const f12=ms[0]+'-01',ag={};S.logs.filter(l=>l.d>=f12).forEach(l=>{ag[l.tb]=ag[l.tb]||{c:0,n:0,h:0};ag[l.tb].c+=l.cost;ag[l.tb].n++;ag[l.tb].h+=+l.hours||0});
  const top=Object.entries(ag).sort((a,b)=>b[1].c-a[1].c).slice(0,5),mx=top.length?top[0][1].c:1;
  $('#dTop').innerHTML=top.length?top.map(([id,o],i)=>{const t=tbOf(id);return `<div class="li click" onclick="tbView('${id}')"><span class="medal" style="background:${MED[i]}">${i+1}</span><div class="meta"><b>${esc(t?t.name:'(đã xóa)')}</b><small>${o.n} lượt · dừng máy ${fmt(o.h)} giờ · ${esc(t?t.dept:'')}</small><div class="pbar"><i style="width:${o.c/mx*100}%;background:linear-gradient(90deg,#ff9466,#f0663a)"></i></div></div><div class="v">${short(o.c)}</div></div>`}).join(''):'<div class="empty">Chưa có chi phí</div>';
  countUp(e)}

/* =========================================================
   LỊCH BẢO TRÌ (tháng)
   ========================================================= */
let CM=TODAYS.slice(0,7);
function occ(p,f,t,m){const o=[];let d=nextOf(p,m),g=0;while(d<=t&&g++<400){if(d>=f)o.push(d);d=step(d,p)}return o}
function renderCal(){const e=$('#page-cal'),m=M(),[y,mo]=CM.split('-').map(Number),first=new Date(y,mo-1,1),last=new Date(y,mo,0);
  const start=new Date(y,mo-1,1-((first.getDay()+6)%7)),f=ymd(first),t=ymd(last),ev={};
  const add=(d,x)=>{(ev[d]=ev[d]||[]).push(x)};
  S.plans.forEach(p=>{if(planSt(p,m)==='off')return;const tt=tbOf(p.tb);occ(p,f,t,m).forEach(d=>add(d,{c:d<TODAYS?'qh':'p',tx:(tt?tt.code+' ':'')+p.task,tip:(tt?tt.name+': ':'')+p.task+' ('+vnDate(d)+')',fn:`logDone('${p.id}')`}))});
  S.logs.forEach(l=>{if(l.d<f||l.d>t)return;const tt=tbOf(l.tb);add(l.d,{c:l.kind==='Sửa chữa'||l.kind==='Thay thế linh kiện'?'sc':'dn2',tx:(tt?tt.code+' ':'')+l.content,tip:l.no+' · '+(tt?tt.name:'')+': '+l.content+(l.cost?' · '+money(l.cost):''),fn:`LGC.open('${l.id}')`})});
  let cells='';for(let i=0;i<42;i++){const d=new Date(start.getFullYear(),start.getMonth(),start.getDate()+i),k=ymd(d),list=ev[k]||[];if(i>=35&&d>last)break;
    cells+=`<div class="cell${d.getMonth()!==mo-1?' out':''}${k===TODAYS?' today':''}"><div class="dn"><b style="cursor:pointer" title="Xem việc trong ngày" onclick="calDay('${k}')">${d.getDate()}</b>${list.length>3?`<span class="more" onclick="calDay('${k}')">+${list.length-3}</span>`:''}</div>${list.slice(0,3).map(x=>`<div class="chipc ${x.c}" data-tip="${esc(x.tip)}" onclick="${x.fn}">${esc(x.tx)}</div>`).join('')}</div>`}
  const plans=S.plans.map(p=>({p,s:planSt(p,m),n:nextOf(p,m)})).filter(x=>x.s!=='off'),qh=plans.filter(x=>x.s==='qh').sort((a,b)=>a.n.localeCompare(b.n)),up=plans.filter(x=>x.n>=TODAYS&&x.n<=addDays(TODAYS,30)).sort((a,b)=>a.n.localeCompare(b.n));
  const it=x=>{const tt=tbOf(x.p.tb),d=diffDays(TODAYS,x.n);return `<div class="li"><div class="meta"><b>${esc(x.p.task)}</b><small>${esc(tt?tt.code+' '+tt.name:'')} · ${vnDate(x.n)} · ${dLeftH(d)}</small></div><button class="btn sm in" onclick="logDone('${x.p.id}')">Ghi nhận</button></div>`};
  e.innerHTML=`<div class="calw"><div class="card"><div class="calh"><button class="btn sm" onclick="calGo(-1)">‹ Tháng trước</button><h3>Tháng ${mo}/${y}</h3><button class="btn sm" onclick="calGo(1)">Tháng sau ›</button><button class="btn sm" onclick="CM=TODAYS.slice(0,7);renderCal()">Hôm nay</button><div style="margin-left:auto" class="muted">${Object.values(ev).flat().filter(x=>x.c==='p'||x.c==='qh').length} việc theo kế hoạch · ${S.logs.filter(l=>l.d>=f&&l.d<=t).length} phiếu đã làm</div></div>
    <div class="calg">${['Thứ 2','Thứ 3','Thứ 4','Thứ 5','Thứ 6','Thứ 7','CN'].map(x=>`<div class="wd">${x}</div>`).join('')}${cells}</div>
    <div class="cleg"><span><i style="background:#3b82f6"></i>Đến hạn theo kế hoạch</span><span><i style="background:var(--danger)"></i>Quá hạn chưa làm</span><span><i style="background:var(--in)"></i>Đã bảo trì</span><span><i style="background:var(--out)"></i>Đã sửa chữa, thay thế</span><span>Bấm vào việc để ghi nhận hoặc xem phiếu</span></div></div>
    <div><div class="card" style="margin-bottom:16px"><div class="card-h"><h3>Quá hạn</h3><span class="cnt-b">${qh.length||''}</span></div><div class="card-b">${qh.length?qh.map(it).join(''):'<div class="empty" style="padding:16px">Không có việc quá hạn</div>'}</div></div>
    <div class="card"><div class="card-h"><h3>30 ngày tới</h3><span class="hint">${up.length} việc</span></div><div class="card-b" style="max-height:520px;overflow:auto">${up.length?up.map(it).join(''):'<div class="empty" style="padding:16px">Không có việc</div>'}</div></div></div></div>`}
function calGo(n){const [y,m]=CM.split('-').map(Number),d=new Date(y,m-1+n,1);CM=d.getFullYear()+'-'+pad(d.getMonth()+1);renderCal()}
function calDay(k){const m=M(),list=[];S.plans.forEach(p=>{if(planSt(p,m)!=='off'&&occ(p,k,k,m).length)list.push(`<div class="li"><div class="meta"><b>${esc(p.task)}</b><small>${esc(tbName(p.tb))} · theo kế hoạch</small></div><button class="btn sm in" onclick="logDone('${p.id}')">Ghi nhận</button></div>`)});
  S.logs.filter(l=>l.d===k).forEach(l=>list.push(`<div class="li click" onclick="LGC.open('${l.id}')"><div class="meta"><b>${esc(l.content)}</b><small>${esc(l.no)} · ${esc(tbName(l.tb))} · ${esc(l.kind)}</small></div><div class="v">${fmt(l.cost)}</div></div>`));
  openModal(`<div class="modal-h"><h3>Ngày ${vnDate(k)}</h3><button class="x" onclick="closeModal()">×</button></div><div class="modal-b">${list.join('')||'<div class="empty">Không có việc</div>'}</div>`,'small')}

/* =========================================================
   THIẾT BỊ
   ========================================================= */
const sOpts=()=>Object.keys(STS).map(k=>[k,STS[k][1]]);
const tbOpts=()=>S.tb.slice().sort((a,b)=>a.code.localeCompare(b.code)).map(t=>[t.id,t.code+' · '+t.name]);
const byOpts=()=>[...new Set(['Tổ bảo trì nội bộ',...S.ncc.map(n=>n.name),...S.logs.map(l=>l.by).filter(Boolean)])];
const findTb=v=>{const s=fold(v);const t=S.tb.find(x=>fold(x.code)===s||fold(x.name)===s||fold(x.code+' · '+x.name)===s);return t?t.id:''};
function tbNextCell(t){const m=M(),ps=S.plans.filter(p=>p.tb===t.id&&planSt(p,m)!=='off');if(!ps.length)return '<span class="muted">-</span>';const p=ps.sort((a,b)=>nextOf(a,m).localeCompare(nextOf(b,m)))[0],d=diffDays(TODAYS,nextOf(p,m));return `${vnDate(nextOf(p,m))}<br>${dLeftH(d)}`}
const TBC=crud({id:'tb',el:'#page-tb',name:'thiết bị',title:'Thiết bị',arr:()=>S.tb,set:a=>S.tb=a,code:{k:'code',pre:'TB',len:3,l:'Mã thiết bị'},ph:'Tìm mã, tên, model, serial, vị trí, người phụ trách...',modal:'wide',
  label:r=>r.code+' '+r.name,search:r=>[r.code,r.name,r.model,r.serial,r.loc,r.owner,r.type,r.dept].join(' '),sort:(a,b)=>a.code.localeCompare(b.code),
  fields:[{k:'code',l:'Mã thiết bị',req:1},{k:'name',l:'Tên thiết bị',req:1},{k:'type',l:'Loại thiết bị',t:'combo',opts:()=>[...new Set(S.tb.map(t=>t.type))]},{k:'model',l:'Model'},{k:'serial',l:'Số serial'},
    {k:'dept',l:'Bộ phận sử dụng',t:'combo',opts:()=>[...new Set(S.tb.map(t=>t.dept))]},{k:'loc',l:'Vị trí đặt'},{k:'owner',l:'Người phụ trách',t:'combo',opts:()=>[...new Set(S.tb.map(t=>t.owner).filter(Boolean))]},
    {k:'buyDate',l:'Ngày mua / đưa vào dùng',t:'date',def:()=>TODAYS},{k:'sup',l:'Nhà cung cấp',t:'select',blank:'(chưa chọn)',opts:()=>S.ncc.map(n=>[n.id,n.name]),imp:v=>{const n=S.ncc.find(x=>fold(x.name)===fold(v)||fold(x.code)===fold(v));return n?n.id:''}},
    {k:'price',l:'Giá mua (₫)',t:'money',def:0},{k:'warEnd',l:'Hạn bảo hành đến ngày',t:'date',hint:'Để trống nếu không có bảo hành'},{k:'status',l:'Hiện trạng',t:'select',opts:sOpts,def:'hd'},{k:'note',l:'Ghi chú',w2:1}],
  filters:[{all:'Mọi bộ phận',opts:()=>[...new Set(S.tb.map(t=>t.dept))],test:(r,v)=>r.dept===v},{all:'Mọi loại',opts:()=>[...new Set(S.tb.map(t=>t.type))],test:(r,v)=>r.type===v},{all:'Mọi hiện trạng',opts:sOpts,test:(r,v)=>r.status===v},{all:'Bảo hành',opts:[['con','Còn bảo hành'],['sap','Sắp hết BH (90 ngày)'],['het','Hết bảo hành']],test:(r,v)=>{if(!r.warEnd)return v==='het';const d=diffDays(TODAYS,r.warEnd);return v==='het'?d<0:v==='sap'?d>=0&&d<=90:d>90}}],
  cols:[{l:'Mã',h:r=>`<b>${esc(r.code)}</b>`},{l:'Thiết bị',h:r=>`<div class="pcell"><b>${esc(r.name)}</b><small>${esc(r.type)} · ${esc(r.model)}</small></div>`},{l:'Serial',h:r=>`<span class="muted">${esc(r.serial)}</span>`},
    {l:'Bộ phận / vị trí',h:r=>`${esc(r.dept)}<br><small class="muted">${esc(r.loc)}</small>`},{l:'Phụ trách',h:r=>esc(r.owner)},{l:'Ngày mua',h:r=>vnDate(r.buyDate)},{l:'Giá mua',cls:'n',h:r=>fmt(r.price)},
    {l:'Bảo hành',h:r=>{const w=wSt(r);return `<span class="tag ${w[0]}">${esc(w[1])}</span>`}},{l:'Hiện trạng',h:r=>stTag(r.status)},{l:'Bảo trì tiếp theo',h:r=>tbNextCell(r)}],
  rowAct:r=>`<button class="btn sm ico" title="Hồ sơ thiết bị" onclick="tbView('${r.id}')">${IC.eye}</button> `,
  foot:rows=>`<tr><td colspan="7">Tổng ${rows.length} thiết bị</td><td class="n">${fmt(sum(rows,r=>r.price))}</td><td colspan="4"></td></tr>`,
  top:()=>{const live=S.tb.filter(t=>t.status!=='tl');return `<div class="stcols">${Object.keys(STS).map(k=>{const ts=S.tb.filter(t=>t.status===k);return `<div class="card stc" style="--c:${STS[k][2]}"><small class="muted">${STS[k][1]}</small><div class="n">${ts.length}</div><small class="muted">${k==='tl'?'Không tính vào lịch bảo trì':pct(live.length?ts.length/live.length*100:0,0)+' thiết bị đang dùng'}</small></div>`}).join('')}</div>`},
  onSave:(r,isNew,old)=>{if(isNew)S.stlog.push({id:'s'+uid(),tb:r.id,d:r.buyDate||TODAYS,from:'',to:r.status,note:'Thêm vào danh mục',by:r.owner||''});else if(old.status!==r.status)S.stlog.push({id:'s'+uid(),tb:r.id,d:TODAYS,from:old.status,to:r.status,note:'Cập nhật trong danh mục thiết bị',by:''})},
  onImport:r=>{r.status=r.status||'hd';S.stlog.push({id:'s'+uid(),tb:r.id,d:r.buyDate||TODAYS,from:'',to:r.status,note:'Nhập từ Excel',by:r.owner||''})},
  canDel:r=>S.logs.some(l=>l.tb===r.id)?`${r.name} đã có nhật ký bảo trì, không xóa được để giữ lịch sử. Đổi hiện trạng sang Thanh lý nếu không dùng nữa.`:null,
  delNote:r=>'Kế hoạch bảo trì và lịch sử hiện trạng của thiết bị này cũng bị xóa.',
  onDel:r=>{S.plans=S.plans.filter(p=>p.tb!==r.id);S.stlog=S.stlog.filter(s=>s.tb!==r.id)}});
function tbView(id){const t=tbOf(id);if(!t)return;const m=M(),n=nccOf(t.sup),ps=S.plans.filter(p=>p.tb===id),ls=S.logs.filter(l=>l.tb===id),w=wSt(t);
  const hist=[...S.stlog.filter(s=>s.tb===id).map(s=>({d:s.d,c:STS[s.to]?STS[s.to][2]:'#64748b',t:`${s.from?STS[s.from][1]+' → ':''}${STS[s.to]?STS[s.to][1]:''}`,s:s.note+(s.by?' · '+s.by:'')})),...ls.map(l=>({d:l.d,c:KCOL[l.kind]||'#64748b',t:`${l.kind}: ${l.content}`,s:`${l.no} · ${l.by||''}${l.cost?' · '+money(l.cost):''}${l.hours?' · dừng '+l.hours+' giờ':''}${l.result==='Chưa xong'?' · chưa xong':''}`}))].sort((a,b)=>b.d.localeCompare(a.d));
  openModal(`<div class="modal-h"><h3>${esc(t.code)} · ${esc(t.name)}</h3>${stTag(t.status)}<button class="x" onclick="closeModal()">×</button></div>
  <div class="modal-b"><div class="prof">${[['Loại',t.type],['Model',t.model],['Số serial',t.serial],['Bộ phận',t.dept],['Vị trí',t.loc],['Người phụ trách',t.owner],['Ngày mua',vnDate(t.buyDate)],['Nhà cung cấp',n?n.name:''],['Giá mua',money(t.price)],['Bảo hành',w[1]],['Tổng chi phí bảo trì',money(sum(ls,l=>l.cost))],['Số lần sửa / dừng máy',ls.filter(l=>l.kind==='Sửa chữa'||l.kind==='Thay thế linh kiện').length+' lần · '+fmt(sum(ls,l=>+l.hours||0))+' giờ']].map(([a,b])=>`<div><small>${a}</small><b>${esc(b||'-')}</b></div>`).join('')}</div>
  <div class="sec-t">Kế hoạch bảo trì</div>${ps.length?`<div class="tbl-wrap" style="margin-bottom:14px"><table><thead><tr><th>Công việc</th><th>Chu kỳ</th><th>Lần gần nhất</th><th>Lần tiếp theo</th><th>Trạng thái</th><th></th></tr></thead><tbody>${ps.map(p=>{const s=planSt(p,m);return `<tr><td>${esc(p.task)}</td><td>${p.cycle} ${p.unit}</td><td>${vnDate(lastOf(p,m))}</td><td>${vnDate(nextOf(p,m))}</td><td><span class="tag ${PST[s][0]}">${PST[s][1]}</span></td><td><button class="btn sm in" onclick="logDone('${p.id}')">Ghi nhận</button></td></tr>`}).join('')}</tbody></table></div>`:`<p class="muted" style="margin-bottom:14px">Chưa có kế hoạch bảo trì. <button class="btn sm" onclick="closeModal();PLC.open(null,{tb:'${id}'})">Thêm kế hoạch</button></p>`}
  <div class="sec-t">Lịch sử thiết bị (${hist.length})</div><div class="tl" style="max-height:330px;overflow:auto;padding-top:4px">${hist.map(h=>`<div class="tli" style="--c:${h.c}"><b>${esc(h.t)}</b><small>${vnDate(h.d)} · ${esc(h.s)}</small></div>`).join('')}</div></div>
  <div class="modal-f"><button class="btn" style="margin-right:auto" onclick="stChange('${id}')">${IC.refresh}Đổi hiện trạng</button><button class="btn" onclick="TBC.open('${id}')">${IC.edit}Sửa</button><button class="btn" onclick="printTb('${id}')">${IC.print}In lý lịch</button><button class="btn pri" onclick="LGC.open(null,{tb:'${id}'})">${IC.plus}Ghi nhật ký</button></div>`,'wide')}
function printTb(id){const t=tbOf(id),n=nccOf(t.sup),k=co(),ls=S.logs.filter(l=>l.tb===id).sort((a,b)=>a.d.localeCompare(b.d)),ps=S.plans.filter(p=>p.tb===id),m=M();
  printHtml(`<div class="vt"><div class="hd"><div><b>${esc(k.name||DOTS)}</b><br>${esc(k.dept||'')}</div><div class="r">Ngày in: ${vnDate(TODAYS)}</div></div>
  <h2>LÝ LỊCH THIẾT BỊ</h2><div class="so">Mã thiết bị: <b>${esc(t.code)}</b></div>
  <table><tbody>${[['Tên thiết bị',t.name,'Loại',t.type],['Model',t.model,'Số serial',t.serial],['Bộ phận sử dụng',t.dept,'Vị trí',t.loc],['Người phụ trách',t.owner,'Hiện trạng',STS[t.status][1]],['Ngày mua',vnDate(t.buyDate),'Nhà cung cấp',n?n.name:''],['Giá mua',fmt(t.price)+' đ','Bảo hành đến',vnDate(t.warEnd)]].map(r=>`<tr><td><b>${r[0]}</b></td><td>${esc(r[1]||'')}</td><td><b>${r[2]}</b></td><td>${esc(r[3]||'')}</td></tr>`).join('')}</tbody></table>
  <div class="ln"><b>Kế hoạch bảo trì định kỳ</b></div><table><thead><tr><th>STT</th><th>Công việc</th><th>Chu kỳ</th><th>Lần gần nhất</th><th>Lần tiếp theo</th><th>Thực hiện</th></tr></thead><tbody>${ps.map((p,i)=>`<tr><td class="c">${i+1}</td><td>${esc(p.task)}</td><td class="c">${p.cycle} ${p.unit}</td><td class="c">${vnDate(lastOf(p,m))}</td><td class="c">${vnDate(nextOf(p,m))}</td><td>${esc(p.by)}</td></tr>`).join('')||'<tr><td colspan="6" class="c">Chưa có</td></tr>'}</tbody></table>
  <div class="ln"><b>Lịch sử bảo trì, sửa chữa</b></div><table><thead><tr><th>STT</th><th>Ngày</th><th>Số phiếu</th><th>Loại</th><th>Nội dung</th><th>Đơn vị thực hiện</th><th>Chi phí</th></tr></thead><tbody>${ls.map((l,i)=>`<tr><td class="c">${i+1}</td><td class="c">${vnDate(l.d)}</td><td class="c">${esc(l.no)}</td><td>${esc(l.kind)}</td><td>${esc(l.content)}</td><td>${esc(l.by)}</td><td class="n">${fmt(l.cost)}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="6" class="c">Cộng</td><td class="n">${fmt(sum(ls,l=>l.cost))}</td></tr></tfoot></table>
  <div class="sdate">Ngày ${TODAYS.slice(8)} tháng ${TODAYS.slice(5,7)} năm ${TODAYS.slice(0,4)}</div><div class="sign" style="--n:2"><div><b>Người lập</b><i>(Ký, họ tên)</i></div><div><b>Trưởng bộ phận</b><i>(Ký, họ tên)</i></div></div></div>`)}

/* =========================================================
   HIỆN TRẠNG THIẾT BỊ
   ========================================================= */
const SF={q:'',to:''};
function renderSt(){const e=$('#page-st');
  e.innerHTML=`<div class="toolbar"><div class="search grow">${IC.search}<input class="inp" id="stQ" placeholder="Tìm thiết bị, lý do..." value="${esc(SF.q)}"></div><select class="inp" id="stTo"><option value="">Mọi hiện trạng mới</option>${sOpts().map(([k,l])=>`<option value="${k}" ${SF.to===k?'selected':''}>${l}</option>`).join('')}</select><button class="btn pri" onclick="stChange()">${IC.refresh}Đổi hiện trạng thiết bị</button></div>
  <div class="stcols">${Object.keys(STS).map(k=>{const ts=S.tb.filter(t=>t.status===k);return `<div class="card stc" style="--c:${STS[k][2]}"><div style="display:flex;justify-content:space-between;align-items:center"><b>${STS[k][1]}</b><span class="n">${ts.length}</span></div><div class="lst">${ts.map(t=>{const lg=S.stlog.filter(s=>s.tb===t.id).sort((a,b)=>b.d.localeCompare(a.d))[0];return `<div onclick="tbView('${t.id}')" title="${esc(lg?lg.note:'')}"><b>${esc(t.code)}</b> ${esc(t.name)}${k!=='hd'&&lg?` <span class="muted">· từ ${vnDate(lg.d)}</span>`:''}</div>`}).join('')||'<span class="muted">Không có</span>'}</div></div>`}).join('')}</div>
  <div class="card"><div class="card-h"><h3>Lịch sử thay đổi hiện trạng</h3><span class="hint">${S.stlog.length} lần</span></div><div class="tbl-wrap" id="stT"></div></div>`;
  $('#stQ').oninput=ev=>{SF.q=ev.target.value;pgReset('stl');stList()};$('#stTo').onchange=ev=>{SF.to=ev.target.value;pgReset('stl');stList()};stList()}
function stList(){const rows=S.stlog.filter(s=>(!SF.to||s.to===SF.to)&&(!SF.q||matchQ(SF.q,tbName(s.tb)+' '+s.note+' '+s.by))).sort((a,b)=>b.d.localeCompare(a.d));
  $('#stT').innerHTML=rows.length?`<table><thead><tr><th>Ngày</th><th>Thiết bị</th><th>Từ</th><th></th><th>Sang</th><th>Lý do / ghi chú</th><th>Người báo</th><th></th></tr></thead><tbody>${pgSlice('stl',rows).map(s=>`<tr><td class="nw">${vnDate(s.d)}</td><td><b>${esc(tbName(s.tb))}</b></td><td>${s.from?stTag(s.from):'<span class="muted">Mới</span>'}</td><td class="muted">→</td><td>${stTag(s.to)}</td><td>${esc(s.note)}</td><td>${esc(s.by)}</td><td class="acts-c"><button class="btn sm ico danger" title="Xóa dòng lịch sử" onclick="stDel('${s.id}')">${IC.trash}</button></td></tr>`).join('')}</tbody></table>${pgBar('stl',rows.length,stList)}`:'<div class="empty">Chưa có thay đổi nào</div>'}
function stChange(id){const t=id?tbOf(id):null;
  openModal(`<div class="modal-h"><h3>Đổi hiện trạng thiết bị</h3><button class="x" onclick="closeModal()">×</button></div><div class="modal-b"><div class="fgrid">
    <div class="fg w2"><label class="f">Thiết bị *</label><select class="inp" id="scT">${tbOpts().map(([v,l])=>`<option value="${v}" ${v===id?'selected':''}>${esc(l)}</option>`).join('')}</select><div class="fhint" id="scCur"></div></div>
    <div class="fg"><label class="f">Hiện trạng mới *</label><select class="inp" id="scS">${sOpts().map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select></div>
    <div class="fg"><label class="f">Ngày</label><input class="inp" type="date" id="scD" value="${TODAYS}"></div>
    <div class="fg w2"><label class="f">Lý do / mô tả</label><input class="inp" id="scN" placeholder="VD: Máy báo lỗi quá nhiệt, dừng máy"></div>
    <div class="fg w2"><label class="f">Người báo</label><input class="inp" id="scB" value="${esc(t?t.owner:'')}"></div></div></div>
  <div class="modal-f"><button class="btn" onclick="closeModal()">Hủy</button><button class="btn pri" onclick="stSave()">${IC.save}Lưu</button></div>`,'small');
  const upd=()=>{const x=tbOf($('#scT').value);$('#scCur').innerHTML=x?'Hiện tại: '+stTag(x.status):'';if(x){const nx={hd:'hong',hong:'sua',sua:'hd',tl:'hd'}[x.status];$('#scS').value=nx}};$('#scT').onchange=upd;upd()}
function stSave(){const t=tbOf($('#scT').value),to=$('#scS').value;if(!t)return toast('Chưa chọn thiết bị','err');if(t.status===to)return toast('Thiết bị đang ở hiện trạng này rồi','err');
  S.stlog.push({id:'s'+uid(),tb:t.id,d:$('#scD').value||TODAYS,from:t.status,to,note:$('#scN').value.trim(),by:$('#scB').value.trim()});t.status=to;save();closeModal();toast(`${t.name}: ${STS[to][1]}`);rerender()}
async function stDel(id){if(!await ask('Xóa dòng lịch sử hiện trạng này? Hiện trạng hiện tại của thiết bị không đổi.'))return;S.stlog=S.stlog.filter(s=>s.id!==id);save();stList()}

/* =========================================================
   NHÀ CUNG CẤP
   ========================================================= */
const NCC=crud({id:'ncc',el:'#page-ncc',name:'nhà cung cấp',title:'Nhà cung cấp',arr:()=>S.ncc,set:a=>S.ncc=a,code:{k:'code',pre:'NCC',len:2,l:'Mã nhà cung cấp'},ph:'Tìm tên, lĩnh vực, người liên hệ...',
  label:r=>r.name,search:r=>[r.code,r.name,r.field,r.contact,r.phone].join(' '),sort:(a,b)=>a.code.localeCompare(b.code),
  fields:[{k:'code',l:'Mã nhà cung cấp',req:1},{k:'name',l:'Tên nhà cung cấp',req:1},{k:'field',l:'Lĩnh vực / mặt hàng'},{k:'contact',l:'Người liên hệ'},{k:'phone',l:'Điện thoại'},{k:'email',l:'Email'},{k:'addr',l:'Địa chỉ',w2:1}],
  cols:[{l:'Mã',h:r=>`<b>${esc(r.code)}</b>`},{l:'Nhà cung cấp',h:r=>`<div class="pcell"><b>${esc(r.name)}</b><small>${esc(r.field)}</small></div>`},{l:'Liên hệ',h:r=>`${esc(r.contact)}<br><small class="muted">${esc(r.phone)}</small>`},
    {l:'Thiết bị đã mua',cls:'n',h:r=>{const ts=S.tb.filter(t=>t.sup===r.id);return ts.length?`${ts.length} TB<br><small class="muted">${short(sum(ts,t=>t.price))} ₫</small>`:'-'}},
    {l:'Chi phí bảo trì 12 tháng',cls:'n',h:r=>{const f=monthsBack(12)[0]+'-01';const v=sum(S.logs.filter(l=>l.by===r.name&&l.d>=f),l=>l.cost);return v?fmt(v):'-'}}],
  canDel:r=>S.tb.some(t=>t.sup===r.id)?r.name+' đang gắn với thiết bị, không xóa được.':null});

/* =========================================================
   KẾ HOẠCH BẢO TRÌ
   ========================================================= */
const PLC=crud({id:'plan',el:'#page-plan',name:'kế hoạch',title:'Kế hoạch bảo trì',arr:()=>S.plans,set:a=>S.plans=a,ph:'Tìm thiết bị, công việc, đơn vị thực hiện...',need:'task',
  label:r=>r.task,search:r=>tbName(r.tb)+' '+r.task+' '+r.by,sort:(a,b)=>nextOf(a).localeCompare(nextOf(b)),
  fields:[{k:'tb',l:'Thiết bị',t:'select',req:1,opts:tbOpts,imp:findTb,w2:1},{k:'task',l:'Công việc bảo trì',req:1,w2:1,ph:'VD: Thay lọc gió, lọc dầu'},{k:'kind',l:'Loại công việc',t:'select',opts:['Bảo trì định kỳ','Kiểm định'],def:'Bảo trì định kỳ'},
    {k:'cycle',l:'Chu kỳ',t:'num',req:1,def:3},{k:'unit',l:'Đơn vị chu kỳ',t:'select',opts:['tháng','ngày'],def:'tháng'},{k:'base',l:'Lần làm gần nhất',t:'date',def:()=>TODAYS,hint:'Mốc tính lần đầu. Sau đó tự lấy theo phiếu nhật ký mới nhất.'},
    {k:'by',l:'Đơn vị thực hiện',t:'combo',opts:byOpts,def:'Tổ bảo trì nội bộ'},{k:'cost',l:'Chi phí dự kiến mỗi lần (₫)',t:'money',def:0},{k:'active',l:'Áp dụng',t:'select',opts:[['1','Đang áp dụng'],['0','Tạm dừng']],def:'1'}],
  filters:[{all:'Mọi trạng thái',opts:Object.keys(PST).map(k=>[k,PST[k][1]]),test:(r,v)=>planSt(r)===v},{all:'Mọi bộ phận',opts:()=>[...new Set(S.tb.map(t=>t.dept))],test:(r,v)=>(tbOf(r.tb)||{}).dept===v},{all:'Mọi loại',opts:['Bảo trì định kỳ','Kiểm định'],test:(r,v)=>r.kind===v}],
  top:()=>{const m=M(),c=k=>S.plans.filter(p=>planSt(p,m)===k).length;return `<div class="kc-grid">${kc({c:'#e0384a',cb:'var(--dangerbg)',icon:IC.warn,label:'Quá hạn',text:c('qh'),unit:'việc',sub:'Đã qua ngày phải làm'})}${kc({c:'#e6a100',cb:'var(--warnbg)',icon:IC.clock,label:'Đến hạn 7 ngày',text:c('dh'),unit:'việc',sub:'Chuẩn bị vật tư, người làm'})}${kc({c:'#0369a1',cb:'#e0f2fe',icon:IC.cal,label:'Sắp tới 30 ngày',text:c('st'),unit:'việc',sub:'Lên lịch trước'})}${kc({c:CSSV('--chu-dao'),cb:'var(--cd-nhat)',icon:IC.list,label:'Tổng kế hoạch',text:S.plans.length,unit:'việc',sub:'Dự kiến 12 tháng '+short(sum(S.plans.filter(p=>p.active!=='0'),p=>(+p.cost||0)*(p.unit==='tháng'?12/(+p.cycle||1):365/(+p.cycle||1))))+' ₫'})}</div>`},
  cols:[{l:'Thiết bị',h:r=>{const t=tbOf(r.tb);return `<div class="pcell"><b>${esc(t?t.name:'(đã xóa)')}</b><small>${esc(t?t.code+' · '+t.dept:'')}</small></div>`}},{l:'Công việc',h:r=>`<div style="min-width:190px">${esc(r.task)}<br><small class="muted">${esc(r.kind)}</small></div>`},{l:'Chu kỳ',cls:'nw',h:r=>`${r.cycle} ${esc(r.unit)}`},
    {l:'Lần gần nhất',cls:'nw',h:r=>vnDate(lastOf(r))||'-'},{l:'Lần tiếp theo',cls:'nw',h:r=>`<b>${vnDate(nextOf(r))}</b>`},{l:'Còn lại',h:r=>planSt(r)==='off'?'<span class="muted">-</span>':dLeftH(dLeft(r))},
    {l:'Trạng thái',h:r=>{const s=planSt(r);return `<span class="tag ${PST[s][0]}">${PST[s][1]}</span>`}},{l:'Thực hiện',h:r=>`<div style="min-width:150px"><small>${esc(r.by)}</small></div>`},{l:'Chi phí dự kiến',cls:'n',h:r=>fmt(r.cost)}],
  rowAct:r=>planSt(r)==='off'?'':`<button class="btn sm in" onclick="logDone('${r.id}')">Ghi nhận</button> `,
  validate:o=>(+o.cycle>0?null:'Chu kỳ phải lớn hơn 0')});
function logDone(pid){const p=S.plans.find(x=>x.id===pid);if(!p)return;closeModal();setTimeout(()=>LGC.open(null,{tb:p.tb,plan:p.id,kind:p.kind,content:p.task,by:p.by,cost:p.cost,d:TODAYS}),50)}

/* =========================================================
   NHẬT KÝ BẢO TRÌ, SỬA CHỮA
   ========================================================= */
const planOpts=()=>S.plans.map(p=>{const t=tbOf(p.tb);return [p.id,(t?t.code+' · ':'')+p.task]});
const LGC=crud({id:'log',el:'#page-log',name:'phiếu bảo trì',title:'Nhật ký bảo trì',arr:()=>S.logs,set:a=>S.logs=a,code:{k:'no',pre:'BT',len:5,l:'Số phiếu'},ph:'Tìm số phiếu, thiết bị, nội dung, đơn vị...',modal:'wide',need:'content',
  label:r=>r.no+' · '+r.content,search:r=>[r.no,tbName(r.tb),r.content,r.by,r.kind].join(' '),sort:(a,b)=>b.d.localeCompare(a.d)||b.no.localeCompare(a.no),
  fields:[{k:'no',l:'Số phiếu',req:1},{k:'d',l:'Ngày thực hiện',t:'date',req:1,def:()=>TODAYS},{k:'tb',l:'Thiết bị',t:'select',req:1,opts:tbOpts,imp:findTb},{k:'kind',l:'Loại công việc',t:'select',opts:KINDS,def:'Sửa chữa'},
    {k:'plan',l:'Theo kế hoạch',t:'select',blank:'Không theo kế hoạch (sửa chữa đột xuất)',opts:planOpts,w2:1,noimp:1},{k:'content',l:'Nội dung công việc',t:'textarea',req:1,w2:1},
    {k:'by',l:'Đơn vị thực hiện',t:'combo',opts:byOpts,def:'Tổ bảo trì nội bộ'},{k:'cost',l:'Chi phí (₫)',t:'money',def:0},{k:'hours',l:'Thời gian dừng máy (giờ)',t:'num',def:0},
    {k:'result',l:'Kết quả',t:'select',opts:['Hoàn thành','Chưa xong'],def:'Hoàn thành'},{k:'stAfter',l:'Hiện trạng thiết bị sau khi làm',t:'select',opts:[['','Giữ nguyên hiện trạng'],['hd','Đang hoạt động'],['sua','Đang sửa'],['hong','Hỏng']],def:'',noimp:1,hint:'Chọn để tự cập nhật hiện trạng và ghi lịch sử'}],
  filters:[{all:'Mọi loại công việc',opts:KINDS,test:(r,v)=>r.kind===v},{all:'Mọi bộ phận',opts:()=>[...new Set(S.tb.map(t=>t.dept))],test:(r,v)=>(tbOf(r.tb)||{}).dept===v},{all:'Mọi thời gian',opts:[['m','Tháng này'],['q','Quý này'],['y','Năm nay']],test:(r,v)=>{const g=rangeOf({m:'month',q:'quarter',y:'year'}[v]);return r.d>=g.from&&r.d<=g.to}},{all:'Mọi kết quả',opts:['Hoàn thành','Chưa xong'],test:(r,v)=>r.result===v}],
  cols:[{l:'Số phiếu',h:r=>`<b>${esc(r.no)}</b>`},{l:'Ngày',cls:'nw',h:r=>vnDate(r.d)},{l:'Thiết bị',h:r=>{const t=tbOf(r.tb);return `<div class="pcell"><b>${esc(t?t.name:'(đã xóa)')}</b><small>${esc(t?t.code+' · '+t.dept:'')}</small></div>`}},
    {l:'Loại',h:r=>`<span class="tag" style="background:${KCOL[r.kind]}1f;color:${KCOL[r.kind]}">${esc(r.kind)}</span>`},{l:'Nội dung',h:r=>`<div style="max-width:300px">${esc(r.content)}</div>`},{l:'Đơn vị thực hiện',h:r=>`<div style="min-width:150px"><small>${esc(r.by)}</small></div>`},
    {l:'Dừng máy',cls:'n',h:r=>r.hours?fmt(r.hours)+' giờ':'-'},{l:'Chi phí',cls:'n',h:r=>`<b>${fmt(r.cost)}</b>`},{l:'Kết quả',h:r=>`<span class="tag ${r.result==='Chưa xong'?'low':'ok'}">${esc(r.result)}</span>`}],
  rowAct:r=>`<button class="btn sm ico" title="In phiếu" onclick="printLog('${r.id}')">${IC.print}</button> `,
  foot:rows=>`<tr><td colspan="7">Tổng ${rows.length} phiếu</td><td class="n">${fmt(sum(rows,r=>+r.hours||0))} giờ</td><td class="n">${fmt(sum(rows,r=>r.cost))}</td><td colspan="2"></td></tr>`,
  afterOpen:r=>{const pl=$('#cf_plan');if(!pl)return;pl.onchange=()=>{const p=S.plans.find(x=>x.id===pl.value);if(!p)return;$('#cf_tb').value=p.tb;$('#cf_kind').value=p.kind;if(!$('#cf_content').value.trim())$('#cf_content').value=p.task;$('#cf_by').value=p.by;if(!parseNum($('#cf_cost').value))$('#cf_cost').value=fmt(p.cost)}},
  validate:(o)=>{if(o.plan){const p=S.plans.find(x=>x.id===o.plan);if(p&&p.tb!==o.tb)return 'Kế hoạch đã chọn thuộc thiết bị khác'}return null},
  onSave:(r)=>{const t=tbOf(r.tb);if(t&&r.stAfter&&t.status!==r.stAfter){S.stlog.push({id:'s'+uid(),tb:t.id,d:r.d,from:t.status,to:r.stAfter,note:'Theo phiếu '+r.no+': '+r.content,by:r.by});t.status=r.stAfter}}});
function printLog(id){const l=S.logs.find(x=>x.id===id);if(!l)return;const t=tbOf(l.tb)||{},k=co(),[y,m,d]=l.d.split('-');
  printHtml(`<div class="vt"><div class="hd"><div><b>${esc(k.name||DOTS)}</b><br>${esc(k.dept||'')}</div><div class="r">Số: <b>${esc(l.no)}</b></div></div>
  <h2>PHIẾU BẢO TRÌ, SỬA CHỮA THIẾT BỊ</h2><div class="dt">Ngày ${d} tháng ${m} năm ${y}</div><br>
  <table><tbody>${[['Thiết bị',t.code+' · '+(t.name||'')],['Model / Serial',(t.model||'')+' / '+(t.serial||'')],['Bộ phận / vị trí',(t.dept||'')+' / '+(t.loc||'')],['Loại công việc',l.kind],['Nội dung thực hiện',l.content],['Đơn vị thực hiện',l.by],['Thời gian dừng máy',(l.hours||0)+' giờ'],['Chi phí',fmt(l.cost)+' đồng ('+docSo(l.cost)+')'],['Kết quả',l.result]].map(r=>`<tr><td style="width:190px"><b>${r[0]}</b></td><td>${esc(r[1])}</td></tr>`).join('')}</tbody></table>
  <div class="ln">Vật tư thay thế, ghi chú thêm: ${DOTS}${DOTS}</div>
  <div class="sdate">Ngày ${d} tháng ${m} năm ${y}</div><div class="sign" style="--n:3"><div><b>Người thực hiện</b><i>(Ký, họ tên)</i></div><div><b>Bộ phận sử dụng</b><i>(Ký, họ tên)</i></div><div><b>Trưởng bộ phận kỹ thuật</b><i>(Ký, họ tên)</i></div></div></div>`)}

/* =========================================================
   BÁO CÁO CHI PHÍ
   ========================================================= */
const RF={f:'',t:'',by:'tb'};
function renderRep(){const e=$('#page-rep');
  if(!e.dataset.built){const g=rangeOf('year');RF.f=g.from;RF.t=TODAYS;
    e.innerHTML=`<div class="toolbar"><div class="seg" id="rQ"><button data-v="month">Tháng này</button><button data-v="prev">Tháng trước</button><button data-v="quarter">Quý này</button><button data-v="year" class="on">Năm nay</button><button data-v="12m">12 tháng</button></div>
      <input type="date" class="inp" id="rF" value="${RF.f}"><span class="muted">đến</span><input type="date" class="inp" id="rT" value="${RF.t}"><button class="btn xl" onclick="exportRep()">${IC.xl}Xuất Excel</button><button class="btn pri" onclick="window.print()">${IC.print}In báo cáo</button></div>
      <div class="toolbar"><div class="seg" id="rBy"><button data-v="tb" class="on">Theo thiết bị</button><button data-v="dept">Theo bộ phận</button><button data-v="kind">Theo loại công việc</button><button data-v="month">Theo tháng</button><button data-v="by">Theo đơn vị thực hiện</button></div></div>
      <div class="print-h"><h2>BÁO CÁO CHI PHÍ BẢO TRÌ, SỬA CHỮA THIẾT BỊ</h2><div id="rPr"></div></div><div class="kc-grid" id="rK"></div><div class="grid-c"><div class="card"><div class="card-h"><h3 id="rCt"></h3></div><div class="card-b" id="rCh"></div></div><div class="card"><div class="card-h"><h3>Cơ cấu theo loại công việc</h3></div><div class="card-b" id="rDn"></div></div></div><div class="card"><div class="tbl-wrap" id="rTb"></div></div>`;
    segBind('#rQ',v=>{if(v==='12m'){RF.f=monthsBack(12)[0]+'-01';RF.t=TODAYS}else{const g=rangeOf(v);RF.f=g.from;RF.t=g.to>TODAYS?TODAYS:g.to}$('#rF').value=RF.f;$('#rT').value=RF.t;renderRep()});
    segBind('#rBy',v=>{RF.by=v;renderRep()});$('#rF').oninput=ev=>{RF.f=ev.target.value;renderRep()};$('#rT').oninput=ev=>{RF.t=ev.target.value;renderRep()};e.dataset.built=1}
  const ls=logCost(RF.f,RF.t),T=sum(ls,l=>l.cost),rows=repRows(ls),L={tb:'thiết bị',dept:'bộ phận',kind:'loại công việc',month:'tháng',by:'đơn vị thực hiện'};
  $('#rPr').textContent=`Từ ngày ${vnDate(RF.f)} đến ngày ${vnDate(RF.t)} · theo ${L[RF.by]}${co().name?' · '+co().name:''}`;
  $('#rK').innerHTML=kc({c:CSSV('--chu-dao'),cb:'var(--cd-nhat)',icon:IC.money,label:'Tổng chi phí',value:T,unit:'₫',sub:`${ls.length} phiếu`})+kc({c:'#f0663a',cb:'var(--outbg)',icon:IC.tool,label:'Sửa chữa, thay thế',value:sum(ls.filter(l=>l.kind==='Sửa chữa'||l.kind==='Thay thế linh kiện'),l=>l.cost),unit:'₫',sub:`${ls.filter(l=>l.kind==='Sửa chữa'||l.kind==='Thay thế linh kiện').length} lần hỏng phải sửa`})+kc({c:'#0ea5b7',cb:'#e0f7fa',icon:IC.clock,label:'Thời gian dừng máy',value:sum(ls,l=>+l.hours||0),unit:'giờ',sub:'Cộng mọi phiếu trong kỳ'})+kc({c:'#8b5cf6',cb:'#f1ebff',icon:IC.cpu,label:'Thiết bị có phát sinh',value:new Set(ls.map(l=>l.tb)).size,unit:'TB',sub:`Trên ${S.tb.length} thiết bị`});
  $('#rCt').textContent='Chi phí theo '+L[RF.by];
  $('#rCh').innerHTML=RF.by==='month'?combo({labels:rows.map(r=>r[0]),bars:[{name:'Chi phí',data:rows.map(r=>r[4]),color:CSSV('--chu-dao')}],H:280,W:560}):hbars(rows.slice(0,10).map(r=>({label:r[1]||r[0],value:r[4],sub:r[2]+' lượt'})),short);
  $('#rDn').innerHTML=donut(KINDS.map(k=>({label:k,value:sum(ls.filter(l=>l.kind===k),l=>l.cost),color:KCOL[k]})).filter(x=>x.value),'Chi phí',short);
  $('#rTb').innerHTML=rows.length?`<table><thead><tr><th class="c">#</th><th>${RF.by==='tb'?'Mã':L[RF.by][0].toUpperCase()+L[RF.by].slice(1)}</th>${RF.by==='tb'?'<th>Thiết bị</th><th>Bộ phận</th>':''}<th class="n">Số lượt</th><th class="n">Dừng máy (giờ)</th><th class="n">Chi phí</th><th class="n">Tỷ trọng</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td class="c muted">${i+1}</td><td><b>${esc(r[0])}</b></td>${RF.by==='tb'?`<td>${esc(r[1])}</td><td>${esc(r[5])}</td>`:''}<td class="n">${fmt(r[2])}</td><td class="n">${fmt(r[3])}</td><td class="n"><b>${fmt(r[4])}</b></td><td class="n">${pct(T?r[4]/T*100:0)}</td></tr>`).join('')}</tbody><tfoot><tr><td></td><td colspan="${RF.by==='tb'?3:1}">TỔNG CỘNG</td><td class="n">${fmt(ls.length)}</td><td class="n">${fmt(sum(ls,l=>+l.hours||0))}</td><td class="n">${fmt(T)}</td><td class="n">100%</td></tr></tfoot></table>`:'<div class="empty">Không có phiếu nào trong kỳ</div>';
  countUp($('#rK'))}
function repRows(ls){const key={tb:l=>l.tb,dept:l=>(tbOf(l.tb)||{}).dept||'(khác)',kind:l=>l.kind,month:l=>mKey(l.d),by:l=>l.by||'(chưa ghi)'}[RF.by];
  const g=groupBy(ls,key);let rows=Object.entries(g).map(([k,a])=>{const t=RF.by==='tb'?tbOf(k):null;return [RF.by==='tb'?(t?t.code:'?'):RF.by==='month'?'T'+(+k.slice(5))+'/'+k.slice(0,4):k,RF.by==='tb'?(t?t.name:'(đã xóa)'):'',a.length,sum(a,l=>+l.hours||0),sum(a,l=>l.cost),RF.by==='tb'?(t?t.dept:''):'',k]});
  return RF.by==='month'?rows.sort((a,b)=>a[6].localeCompare(b[6])):rows.sort((a,b)=>b[4]-a[4])}
function exportRep(){const ls=logCost(RF.f,RF.t),rows=repRows(ls),isT=RF.by==='tb';
  XLSX.save(`Chi phi bao tri ${RF.f} den ${RF.t}`,[{name:'Chi phí bảo trì',title:'BÁO CÁO CHI PHÍ BẢO TRÌ, SỬA CHỮA',subtitles:[co().name||'',`Từ ngày ${vnDate(RF.f)} đến ngày ${vnDate(RF.t)}`],totals:true,
    columns:[{label:'STT',type:'int',width:6},{label:isT?'Mã TB':'Nhóm',width:isT?9:26},...(isT?[{label:'Thiết bị',width:30},{label:'Bộ phận',width:18}]:[]),{label:'Số lượt',type:'int',sum:true},{label:'Dừng máy (giờ)',type:'num',sum:true},{label:'Chi phí',type:'money',sum:true}],
    rows:rows.map((r,i)=>[i+1,r[0],...(isT?[r[1],r[5]]:[]),r[2],r[3],r[4]])},
    {name:'Chi tiết phiếu',title:'CHI TIẾT PHIẾU BẢO TRÌ, SỬA CHỮA',columns:logCols(),rows:ls.sort((a,b)=>a.d.localeCompare(b.d)).map(logRow),totals:true}])}

/* =========================================================
   XUẤT EXCEL TOÀN BỘ
   ========================================================= */
const logCols=()=>[{label:'Số phiếu',width:10},{label:'Ngày',type:'date'},{label:'Mã TB',width:9},{label:'Thiết bị',width:28},{label:'Bộ phận',width:16},{label:'Loại công việc',width:16},{label:'Nội dung',width:40},{label:'Đơn vị thực hiện',width:30},{label:'Dừng máy (giờ)',type:'num',sum:true},{label:'Chi phí',type:'money',sum:true},{label:'Kết quả',width:12}];
const logRow=l=>{const t=tbOf(l.tb)||{};return [l.no,l.d,t.code,t.name,t.dept,l.kind,l.content,l.by,+l.hours||0,l.cost,l.result]};
function sheetsAll(){const m=M();
  return [{name:'Thiết bị',title:'DANH MỤC THIẾT BỊ',totals:true,columns:[{label:'Mã TB',width:9},{label:'Tên thiết bị',width:30},{label:'Loại',width:16},{label:'Model',width:16},{label:'Serial',width:16},{label:'Bộ phận',width:18},{label:'Vị trí',width:18},{label:'Người phụ trách',width:18},{label:'Ngày mua',type:'date'},{label:'Nhà cung cấp',width:34},{label:'Giá mua',type:'money',sum:true},{label:'Hạn bảo hành',type:'date'},{label:'Tình trạng BH',width:22},{label:'Hiện trạng',width:14},{label:'Ghi chú',width:20}],
      rows:S.tb.slice().sort((a,b)=>a.code.localeCompare(b.code)).map(t=>[t.code,t.name,t.type,t.model,t.serial,t.dept,t.loc,t.owner,t.buyDate,(nccOf(t.sup)||{}).name||'',t.price,t.warEnd,wSt(t)[1],STS[t.status][1],t.note])},
    {name:'Nhà cung cấp',title:'NHÀ CUNG CẤP',columns:[{label:'Mã',width:8},{label:'Tên nhà cung cấp',width:40},{label:'Lĩnh vực',width:26},{label:'Người liên hệ',width:18},{label:'Điện thoại',width:15},{label:'Email',width:22},{label:'Địa chỉ',width:36},{label:'Số thiết bị đã mua',type:'int'}],rows:S.ncc.map(n=>[n.code,n.name,n.field,n.contact,n.phone,n.email,n.addr,S.tb.filter(t=>t.sup===n.id).length])},
    {name:'Kế hoạch bảo trì',title:'KẾ HOẠCH BẢO TRÌ BẢO DƯỠNG',columns:[{label:'Mã TB',width:9},{label:'Thiết bị',width:28},{label:'Bộ phận',width:16},{label:'Công việc',width:40},{label:'Loại',width:15},{label:'Chu kỳ',type:'int',width:8},{label:'Đơn vị',width:8},{label:'Lần gần nhất',type:'date'},{label:'Lần tiếp theo',type:'date'},{label:'Còn lại (ngày)',type:'int',width:10},{label:'Trạng thái',width:12},{label:'Đơn vị thực hiện',width:30},{label:'Chi phí dự kiến',type:'money'}],
      rows:S.plans.slice().sort((a,b)=>nextOf(a,m).localeCompare(nextOf(b,m))).map(p=>{const t=tbOf(p.tb)||{};return [t.code,t.name,t.dept,p.task,p.kind,+p.cycle,p.unit,lastOf(p,m),nextOf(p,m),diffDays(TODAYS,nextOf(p,m)),PST[planSt(p,m)][1],p.by,p.cost]})},
    {name:'Nhật ký bảo trì',title:'NHẬT KÝ BẢO TRÌ, SỬA CHỮA',columns:logCols(),rows:S.logs.slice().sort((a,b)=>a.d.localeCompare(b.d)).map(logRow),totals:true},
    {name:'Lịch sử hiện trạng',title:'LỊCH SỬ THAY ĐỔI HIỆN TRẠNG',columns:[{label:'Ngày',type:'date'},{label:'Mã TB',width:9},{label:'Thiết bị',width:28},{label:'Từ',width:14},{label:'Sang',width:14},{label:'Lý do / ghi chú',width:46},{label:'Người báo',width:18}],
      rows:S.stlog.slice().sort((a,b)=>a.d.localeCompare(b.d)).map(s=>{const t=tbOf(s.tb)||{};return [s.d,t.code,t.name,s.from?STS[s.from][1]:'Mới',STS[s.to]?STS[s.to][1]:'',s.note,s.by]})}]}

boot();
